import boto3

def query_recent_metric_data(metric_name, namespace, period, start_time, end_time):
    cloudwatch = boto3.client('cloudwatch')
    response = cloudwatch.get_metric_data(
        MetricDataQueries=[
            {
                'Id':'myQuery',
                'MetricStat': {
                    'Metric': {
                        'Namespace': namespace,
                        'MetricName': metric_name,
                        'Dimensions': [
                            {
                                'Name': 'InstanceId',
                                'Value': 'i-0123456789abcdef0'  # Example dimension, replace with actual dimension
                            },
                        ]
                    },
                    'Period': period,
                    'Stat': 'Average'
                },
                'ReturnData': True
            },
        ],
        StartTime=start_time,
        EndTime=end_time
    )
    return response['MetricDataResults'][0]['Values'] if response['MetricDataResults'] else []
